using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Providers.WeChat.Ads;
using MiniFramework.Tests.WeChatAds;
using NUnit.Framework;
using UnityEngine.TestTools;
public sealed class WeChatRewardedBridgeTests
{
    static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
    sealed class Env
    {
        public readonly RewardedApiFixture Api=new RewardedApiFixture();
        public readonly CallbackSinkFixture Sink=new CallbackSinkFixture();
        public readonly WeChatRewardedBackend Backend;
        public readonly List<IRewardedAdAttempt> Tickets=new List<IRewardedAdAttempt>();
        public Env(){Backend=new WeChatRewardedBackend(Api,RewardedApiFixture.Placements);}
        public IRewardedAdAttempt New(string id="a"){var t=Backend.Create("generation",id,"revive",Sink);Tickets.Add(t);return t;}
        public RewardedApiFixture.Handle Handle=>Api.Handles.Last();
    }
    readonly List<Env> envs=new List<Env>();Env New(){var e=new Env();envs.Add(e);return e;}
    static void Check(Result r)=>Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);
    static async UniTask Frames(int n=4){for(int i=0;i<n;i++)await UniTask.Yield();}
    static async UniTask<IRewardedAdAttempt> Loaded(Env e){var t=e.New();Check(await t.LoadAsync());return t;}
    [UnityTearDown]public IEnumerator Teardown()=>UniTask.ToCoroutine(async()=>{
        foreach(var e in envs){e.Sink.Accept=true;e.Sink.Throw=false;foreach(var h in e.Api.Handles){h.FailRelease=h.ThrowRelease=false;h.CompleteLoad();h.CompleteAck();h.Close(false);h.CompleteRelease();}await Frames(6);foreach(var t in e.Tickets){var r=await t.CleanupAsync(Cleanup);if(!r.IsSuccess){await Frames(6);Check(await t.CleanupAsync(Cleanup));}}Assert.AreEqual(0,e.Backend.RetainedAttempts);Assert.AreEqual(0,e.Backend.ActiveAttemptCount);}envs.Clear();});
    [UnityTest]public IEnumerator ShowAcknowledgementIsNotPresentationCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync().Preserve();await Frames();Assert.AreEqual(UniTaskStatus.Pending,show.Status);CollectionAssert.AreEqual(new[]{AdCallbackKind.Started},e.Sink.Facts.Select(f=>f.Kind));Assert.IsFalse((await t.CleanupAsync(Cleanup)).IsSuccess);Assert.AreEqual(0,e.Handle.Releases);e.Handle.Close(true);Check(await show);});
    [UnityTest]public IEnumerator ExplicitTrueCloseProducesOrderedCorrelatedFacts()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync();e.Handle.Close(true);Check(await show);CollectionAssert.AreEqual(new[]{AdCallbackKind.Started,AdCallbackKind.Completed,AdCallbackKind.Closed},e.Sink.Facts.Select(f=>f.Kind));CollectionAssert.AreEqual(new long[]{1,2,3},e.Sink.Facts.Select(f=>f.Sequence));Assert.IsTrue(e.Sink.Facts.All(f=>f.Generation=="generation"&&f.AttemptId=="a"));});
    [UnityTest]public IEnumerator EarlyCloseNeverCompletesReward()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync();e.Handle.Close(false);Check(await show);Assert.IsFalse(e.Sink.Facts.Any(f=>f.Kind==AdCallbackKind.Completed));Assert.AreEqual(AdCallbackKind.Closed,e.Sink.Facts.Last().Kind);});
    [UnityTest]public IEnumerator UnknownCloseCannotProveCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync();e.Handle.Close(null);Check(await show);Assert.IsFalse(e.Sink.Facts.Any(f=>f.Kind==AdCallbackKind.Completed));});
    [UnityTest]public IEnumerator DuplicateCloseKeepsFirstTerminal()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync();e.Handle.Close(false);e.Handle.Close(true);e.Handle.Close(true);Check(await show);Assert.AreEqual(2,e.Sink.Facts.Count);});
    [UnityTest]public IEnumerator ErrorAfterCloseCannotRewriteFact()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync();e.Handle.Close(true);e.Handle.Error();Check(await show);Assert.AreEqual(3,e.Sink.Facts.Count);Assert.IsFalse(e.Sink.Facts.Any(f=>f.Kind==AdCallbackKind.Failed));});
    [UnityTest]public IEnumerator CloseAfterErrorCannotGrantCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync();e.Handle.Error(ErrorKind.NoFill);e.Handle.Close(true);var r=await show;Assert.AreEqual(ErrorKind.NoFill,r.Error.Kind);Assert.IsFalse(e.Sink.Facts.Any(f=>f.Kind==AdCallbackKind.Completed));Assert.AreEqual("wechat.ads.no_fill",e.Sink.Facts.Last().Error.Value.Code);Assert.AreEqual("",r.Error.Message);});
    [UnityTest]public IEnumerator CloseBeforeAcknowledgementWaitsForBothSignals()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>h.HoldAck=true;var t=await Loaded(e);var show=t.ShowAsync().Preserve();e.Handle.Close(true);await Frames();Assert.AreEqual(UniTaskStatus.Pending,show.Status);Assert.AreEqual(0,e.Sink.Facts.Count);e.Handle.CompleteAck();Check(await show);Assert.AreEqual(3,e.Sink.Facts.Count);});
    [UnityTest]public IEnumerator RejectedShowCannotRewardBufferedClose()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>{h.CloseDuringAck=true;h.AckResult=Result.Failure(RewardedApiFixture.Fault(ErrorKind.PermissionDenied));};var t=await Loaded(e);var r=await t.ShowAsync();Assert.AreEqual(ErrorKind.PermissionDenied,r.Error.Kind);Assert.AreEqual(1,e.Sink.Facts.Count);Assert.AreEqual(AdCallbackKind.Failed,e.Sink.Facts[0].Kind);});
    [UnityTest]public IEnumerator SinkBackpressureRetainsOwnershipWithoutNativeReplay()=>UniTask.ToCoroutine(async()=>{var e=New();e.Sink.Accept=false;var t=await Loaded(e);var show=t.ShowAsync().Preserve();e.Handle.Close(true);await Frames();Assert.AreEqual(UniTaskStatus.Pending,show.Status);Assert.IsFalse((await t.CleanupAsync(Cleanup)).IsSuccess);Assert.AreEqual(1,e.Handle.Shows);e.Sink.Accept=true;Check(await show);Assert.AreEqual(3,e.Sink.Facts.Count);Assert.AreEqual(1,e.Handle.Shows);});
    [UnityTest]public IEnumerator ThrowingSinkDoesNotDropOwnedTerminal()=>UniTask.ToCoroutine(async()=>{var e=New();e.Sink.Throw=true;var t=await Loaded(e);var show=t.ShowAsync().Preserve();e.Handle.Close(false);await Frames();Assert.AreEqual(UniTaskStatus.Pending,show.Status);e.Sink.Throw=false;Check(await show);Assert.AreEqual(2,e.Sink.Facts.Count);});
    [UnityTest]public IEnumerator WorkerCloseIsDeliveredThroughSink()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync();var worker=new Thread(()=>e.Handle.Close(true));worker.Start();worker.Join();Check(await show);Assert.AreEqual(3,e.Sink.Facts.Count);});
    [UnityTest]public IEnumerator CancelLoadWaitsForActualLoadCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>h.HoldLoad=true;var t=e.New();var load=t.LoadAsync().Preserve();Check(t.CancelLoad());Check(t.CancelLoad());Assert.AreEqual(1,e.Handle.Cancels);Assert.AreEqual(UniTaskStatus.Pending,load.Status);Assert.IsFalse((await t.CleanupAsync(Cleanup)).IsSuccess);Assert.AreEqual(0,e.Handle.Releases);e.Handle.CompleteLoad();Check(await load);Assert.IsFalse((await t.ShowAsync()).IsSuccess);});
    [UnityTest]public IEnumerator ColdCancelNeverCreatesNativeHandle()=>UniTask.ToCoroutine(async()=>{var e=New();var t=e.New();Check(t.CancelLoad());Assert.IsFalse((await t.LoadAsync()).IsSuccess);Assert.AreEqual(0,e.Api.Creates);});
    [UnityTest]public IEnumerator VisibleAdCannotBeCanceledOrReleasedEarly()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);var show=t.ShowAsync();Assert.IsFalse(t.CancelLoad().IsSuccess);Assert.IsFalse((await t.CleanupAsync(Cleanup)).IsSuccess);Assert.AreEqual(0,e.Handle.Cancels);Assert.AreEqual(0,e.Handle.Releases);e.Handle.Close(false);Check(await show);});
    [UnityTest]public IEnumerator NoFillLoadRemainsDistinctAndNeverShows()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>h.LoadResult=Result.Failure(RewardedApiFixture.Fault(ErrorKind.NoFill));var t=e.New();var r=await t.LoadAsync();Assert.AreEqual(ErrorKind.NoFill,r.Error.Kind);Assert.AreEqual("wechat.ads.no_fill",r.Error.Code);Assert.AreEqual("",r.Error.Message);Assert.IsFalse((await t.ShowAsync()).IsSuccess);Assert.AreEqual(0,e.Handle.Shows);});
    [UnityTest]public IEnumerator ErrorBetweenLoadAndShowPreventsShow()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);e.Handle.Error(ErrorKind.Network);var r=await t.ShowAsync();Assert.AreEqual(ErrorKind.Network,r.Error.Kind);Assert.AreEqual(0,e.Handle.Shows);});
    [UnityTest]public IEnumerator FailedReleaseRetainsLeaseAndRetriesOnlyRelease()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);e.Handle.FailRelease=true;Assert.IsFalse((await t.CleanupAsync(Cleanup)).IsSuccess);Assert.AreEqual(1,e.Backend.ActiveAttemptCount);Assert.IsFalse((await t.ShowAsync()).IsSuccess);e.Handle.FailRelease=false;Check(await t.CleanupAsync(Cleanup));Assert.AreEqual(2,e.Handle.Releases);Assert.AreEqual(1,e.Handle.Loads);Assert.AreEqual(0,e.Handle.Shows);});
    [UnityTest]public IEnumerator PendingReleaseIsSingleFlight()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>h.HoldRelease=true;var t=await Loaded(e);var first=t.CleanupAsync(Cleanup).Preserve();var second=t.CleanupAsync(Cleanup).Preserve();Assert.AreEqual(1,e.Handle.Releases);Assert.AreEqual(1,e.Backend.ActiveAttemptCount);e.Handle.CompleteRelease();Check(await first);Check(await second);});
    [UnityTest]public IEnumerator ColdCleanupRemovesManagedOwnershipOnly()=>UniTask.ToCoroutine(async()=>{var e=New();var t=e.New();Check(await t.CleanupAsync(Cleanup));Check(await t.CleanupAsync(Cleanup));Assert.IsFalse((await t.LoadAsync()).IsSuccess);Assert.AreEqual(0,e.Api.Creates);Assert.AreEqual(0,e.Backend.RetainedAttempts);});
    [UnityTest]public IEnumerator SecondAttemptCannotLoadBeforeFirstRelease()=>UniTask.ToCoroutine(async()=>{var e=New();await Loaded(e);var second=e.New("b");var r=await second.LoadAsync();Assert.AreEqual("wechat.ads.busy",r.Error.Code);Assert.AreEqual(1,e.Api.Creates);Check(await second.CleanupAsync(Cleanup));Assert.AreEqual(1,e.Backend.ActiveAttemptCount);});
    [UnityTest]public IEnumerator LoadExceptionRemainsOwnedUntilCleanup()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>h.ThrowLoad=true;var t=e.New();Assert.IsFalse((await t.LoadAsync()).IsSuccess);Assert.AreEqual(1,e.Backend.RetainedAttempts);Assert.AreEqual(0,e.Handle.Releases);Check(await t.CleanupAsync(Cleanup));});
    [UnityTest]public IEnumerator ShowExceptionBecomesFailedFact()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>h.ThrowShow=true;var t=await Loaded(e);Assert.IsFalse((await t.ShowAsync()).IsSuccess);Assert.AreEqual(AdCallbackKind.Failed,e.Sink.Facts.Single().Kind);});
    [UnityTest]public IEnumerator ReleasedOldCallbacksCannotAffectNewAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();var first=await Loaded(e);var old=e.Handle;Check(await first.CleanupAsync(Cleanup));var next=e.New("b");Check(await next.LoadAsync());var show=next.ShowAsync().Preserve();old.Close(true);old.Error();await Frames();Assert.AreEqual(UniTaskStatus.Pending,show.Status);e.Handle.Close(false);Check(await show);Assert.IsFalse(e.Sink.Facts.Any(f=>f.AttemptId=="b"&&f.Kind==AdCallbackKind.Completed));});
    [UnityTest]public IEnumerator CleanupDuringLoadBlocksLaterShow()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>h.HoldLoad=true;var t=e.New();var load=t.LoadAsync();Assert.IsFalse((await t.CleanupAsync(Cleanup)).IsSuccess);e.Handle.CompleteLoad();Check(await load);Assert.IsFalse((await t.ShowAsync()).IsSuccess);Assert.AreEqual(0,e.Handle.Shows);});
    [UnityTest]public IEnumerator WorkerCommandsNeverEnterApi()=>UniTask.ToCoroutine(async()=>{var e=New();var t=e.New();Result load=default,show=default,cleanup=default,cancel=default;var worker=new Thread(()=>{load=t.LoadAsync().GetAwaiter().GetResult();show=t.ShowAsync().GetAwaiter().GetResult();cleanup=t.CleanupAsync(Cleanup).GetAwaiter().GetResult();cancel=t.CancelLoad();});worker.Start();worker.Join();Assert.IsFalse(load.IsSuccess||show.IsSuccess||cleanup.IsSuccess||cancel.IsSuccess);Assert.AreEqual(0,e.Api.Creates);await Frames(1);});
    [UnityTest]public IEnumerator NullHandleFailsWithoutLosingManagedTicket()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.NullCreate=true;var t=e.New();Assert.IsFalse((await t.LoadAsync()).IsSuccess);Check(await t.CleanupAsync(Cleanup));Assert.AreEqual(0,e.Backend.RetainedAttempts);});
    [UnityTest]public IEnumerator ColdFactoryExceptionIsSanitized()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.ThrowCreate=true;var t=e.New();var r=await t.LoadAsync();Assert.IsFalse(r.IsSuccess);Assert.AreEqual("",r.Error.Message);Check(await t.CleanupAsync(Cleanup));});
    [UnityTest]public IEnumerator RepeatedLoadAndShowNeverReplayNativeCommands()=>UniTask.ToCoroutine(async()=>{var e=New();var t=await Loaded(e);Assert.IsFalse((await t.LoadAsync()).IsSuccess);var show=t.ShowAsync();Assert.IsFalse((await t.ShowAsync()).IsSuccess);e.Handle.Close(true);Check(await show);Assert.AreEqual(1,e.Handle.Loads);Assert.AreEqual(1,e.Handle.Shows);});
    [UnityTest]public IEnumerator ErrorEventDuringLoadDoesNotFakeActualCompletion()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.Configure=h=>h.HoldLoad=true;var t=e.New();var load=t.LoadAsync().Preserve();e.Handle.Error(ErrorKind.PermissionDenied);await Frames();Assert.AreEqual(UniTaskStatus.Pending,load.Status);e.Handle.CompleteLoad();var r=await load;Assert.AreEqual(ErrorKind.PermissionDenied,r.Error.Kind);Assert.IsFalse((await t.ShowAsync()).IsSuccess);});
}
